(5524102, 796713, 106233, '<td valign="top">beautiful light...</td>', 'beautiful light...', '2009-06-11 14:01:37.000000', NULL, 1),
(5524145, 797411, 30982, '<td valign="top">Excellent composition - very well balanced - and wonderful scrunched up face of your subject!  Text is nicely done as well.</td>', 'Excellent composition - very well balanced - and wonderful scrunched up face of your subject!  Text is nicely done as well.', '2009-06-11 14:56:39.000000', NULL, 1),
(5524147, 796713, 30982, '<td valign="top">Holy cow - really does look like a poster!  Is the background real or have they set it up to look that way?  Or is this not a zoo at all?  Excellent light, comp, color, focus, etc.</td>', 'Holy cow - really does look like a poster!  Is the background real or have they set it up to look that way?  Or is this not a zoo at all?  Excellent light, comp, color, focus, etc.', '2009-06-11 14:57:43.000000', NULL, 1),
(5524148, 797430, 30982, '<td valign="top">Wonderful intensity from your "model"!  Nicely done presentation, from teh photograph to the layout to the text.</td>', 'Wonderful intensity from your "model"!  Nicely done presentation, from teh photograph to the layout to the text.', '2009-06-11 14:58:11.000000', NULL, 1),
(5524149, 797511, 30982, '<td valign="top">Very cool text effects and the shot is composed nicely to support that text.  Cute critter, too!</td>', 'Very cool text effects and the shot is composed nicely to support that text.  Cute critter, too!', '2009-06-11 14:58:48.000000', NULL, 1),
(5524153, 797324, 30982, '<td valign="top">Nice catch of the interaction, and babies with their moms always make good advertising for a zoo.  Good use of the diagonal in the composition.</td>', 'Nice catch of the interaction, and babies with their moms always make good advertising for a zoo.  Good use of the diagonal in the composition.', '2009-06-11 15:01:16.000000', NULL, 1),
(5524154, 797342, 30982, '<td valign="top">Meerkats are always a winner.  :-)  Nice font/text - is that what the zoo uses?</td>', 'Meerkats are always a winner.  :-)  Nice font/text - is that what the zoo uses?', '2009-06-11 15:05:01.000000', NULL, 1),
(5524155, 796993, 30982, '<td valign="top">Good text info!  And love that scratched up nose.</td>', 'Good text info!  And love that scratched up nose.', '2009-06-11 15:05:22.000000', NULL, 1),
(5524156, 797263, 30982, '<td valign="top">Very cool idea!  They do look like they''re on display.</td>', 'Very cool idea!  They do look like they''re on display.', '2009-06-11 15:05:47.000000', NULL, 1),
(5524158, 796788, 30982, '<td valign="top">I wonder if those cats prefer a Range Rover over say, a Jeep?  Good "slogan" for your ad!</td>', 'I wonder if those cats prefer a Range Rover over say, a Jeep?  Good "slogan" for your ad!', '2009-06-11 15:06:23.000000', NULL, 1),
(5524162, 797406, 30982, '<td valign="top">Love the beard!  Nice font choice and a good wry smile from your model.</td>', 'Love the beard!  Nice font choice and a good wry smile from your model.', '2009-06-11 15:07:31.000000', NULL, 1),
(5524164, 797471, 30982, '<td valign="top">Excellent sentiment!  Good kitten shot to go with it, too.  Such a sweet face!</td>', 'Excellent sentiment!  Good kitten shot to go with it, too.  Such a sweet face!', '2009-06-11 15:08:12.000000', NULL, 1),
(5524165, 797510, 30982, '<td valign="top">Awesome macro!  Really vibrant, perfectly composed.</td>', 'Awesome macro!  Really vibrant, perfectly composed.', '2009-06-11 15:08:37.000000', NULL, 1),
(5524169, 797482, 93927, '<td valign="top">lovely</td>', 'lovely', '2009-06-11 15:12:06.000000', NULL, 1),
(5524175, 797452, 93927, '<td valign="top">LOL<br/>i think he likes you!</td>', 'LOLi think he likes you!', '2009-06-11 15:14:17.000000', NULL, 1),
(5524221, 797219, 30982, '<td valign="top">Heh!  He certainly is wide-eyed!  The orange goes nicely with the tiger theme.</td>', 'Heh!  He certainly is wide-eyed!  The orange goes nicely with the tiger theme.', '2009-06-11 16:06:13.000000', NULL, 1),
(5524222, 795947, 30982, '<td valign="top">Very good poster style design - looks professional.  Nice detail on the elephant</td>', 'Very good poster style design - looks professional.  Nice detail on the elephant', '2009-06-11 16:06:53.000000', NULL, 1),
(5524224, 797349, 30982, '<td valign="top">Cute!!  Good look from your model, nice smile, and love the curly fur!  Nice sentiment about the hug, too.</td>', 'Cute!!  Good look from your model, nice smile, and love the curly fur!  Nice sentiment about the hug, too.', '2009-06-11 16:07:34.000000', NULL, 1),
(5524225, 797222, 30982, '<td valign="top">Only if they have their jaws held shut with a rubber band... Almost needs a bit of background to show some context of the zoo.  Very nice touch with the shadowed text.</td>', 'Only if they have their jaws held shut with a rubber band... Almost needs a bit of background to show some context of the zoo.  Very nice touch with the shadowed text.', '2009-06-11 16:08:29.000000', NULL, 1),
(5524226, 797434, 30982, '<td valign="top">What amazing colors on the bird!</td>', 'What amazing colors on the bird!', '2009-06-11 16:08:44.000000', NULL, 1),
(5524227, 797155, 30982, '<td valign="top">Heh - he''s got it made!  I don''t suppose he has a grill set up nearby, and a beer fridge... Nice layout - well designed.</td>', 'Heh - he''s got it made!  I don''t suppose he has a grill set up nearby, and a beer fridge... Nice layout - well designed.', '2009-06-11 16:10:02.000000', NULL, 1),
(5524237, 796809, 30982, '<td valign="top">Good shot - the background is especially effective.  I really like the way you made it an educational poster.  Minor critique - the wording of the fact makes it seem like the offspring are produced already two months.</td>', 'Good shot - the background is especially effective.  I really like the way you made it an educational poster.  Minor critique - the wording of the fact makes it seem like the offspring are produced already two months.', '2009-06-11 16:18:04.000000', NULL, 1),
(5524238, 797247, 30982, '<td valign="top">Made me smile!  Great eyes and really does look like he''s saying that.</td>', 'Made me smile!  Great eyes and really does look like he''s saying that.', '2009-06-11 16:18:27.000000', NULL, 1),
(5524239, 797236, 30982, '<td valign="top">Excellent detail on the kitty and very good layout.  I like the wee bit of motion in the back paw - like she''s a bit peeved you interrupted her grooming to get her picture.</td>', 'Excellent detail on the kitty and very good layout.  I like the wee bit of motion in the back paw - like she''s a bit peeved you interrupted her grooming to get her picture.', '2009-06-11 16:19:18.000000', NULL, 1),
(5524240, 797116, 30982, '<td valign="top">Heh!  Cute phrasing!  Nice layout as well.</td>', 'Heh!  Cute phrasing!  Nice layout as well.', '2009-06-11 16:19:42.000000', NULL, 1),
(5524242, 797325, 30982, '<td valign="top">This guy really is adorable.  I''m sure there''s an eye or two under there somewhere... he''s got great hair!  Nice detail on the horn, and really nice light.</td>', 'This guy really is adorable.  I''m sure there''s an eye or two under there somewhere... he''s got great hair!  Nice detail on the horn, and really nice light.', '2009-06-11 16:20:23.000000', NULL, 1),
(5524243, 797096, 30982, '<td valign="top">Very clever "ad" and a very clever critter!  Nice job of capturing this to show how well it blends in, but letting us see it clearly as well.</td>', 'Very clever "ad" and a very clever critter!  Nice job of capturing this to show how well it blends in, but letting us see it clearly as well.', '2009-06-11 16:21:06.000000', NULL, 1),
(5524244, 797502, 30982, '<td valign="top">Very appropriate for this challenge - the kind of thing one would expect to see as an ad for the zoo!</td>', 'Very appropriate for this challenge - the kind of thing one would expect to see as an ad for the zoo!', '2009-06-11 16:21:37.000000', NULL, 1),
(5524245, 797405, 30982, '<td valign="top">He''s having a particularly good hair day!</td>', 'He''s having a particularly good hair day!', '2009-06-11 16:22:02.000000', NULL, 1),
(5524246, 797302, 30982, '<td valign="top">Very good shot very well composed to make use of the space for the lettering.  I really like the way you''ve used overlays so the photograph still shows through, and nice use of the blurred foreground.</td>', 'Very good shot very well composed to make use of the space for the lettering.  I really like the way you''ve used overlays so the photograph still shows through, and nice use of the blurred foreground.', '2009-06-11 16:22:59.000000', NULL, 1),
(5524248, 797118, 30982, '<td valign="top">Good shot of one of natures not so cute critters.  I like the bold colors used for the text and the varying styles.</td>', 'Good shot of one of natures not so cute critters.  I like the bold colors used for the text and the varying styles.', '2009-06-11 16:23:37.000000', NULL, 1),
(5524249, 797403, 30982, '<td valign="top">I like how it seems like this guy is most definitely posing for you - almost a glamour shot pose!</td>', 'I like how it seems like this guy is most definitely posing for you - almost a glamour shot pose!', '2009-06-11 16:24:08.000000', NULL, 1),
(5524250, 797404, 30982, '<td valign="top">Excellent composition and use of space with respect to the lettering.  Good shot of the critter, too!</td>', 'Excellent composition and use of space with respect to the lettering.  Good shot of the critter, too!', '2009-06-11 16:24:38.000000', NULL, 1),
(5524251, 797448, 30982, '<td valign="top">I like the B&amp;W used here - he has a sorta sad, longing, pensive kind of look.  Nicely composed.</td>', 'I like the B&W used here - he has a sorta sad, longing, pensive kind of look.  Nicely composed.', '2009-06-11 16:25:11.000000', NULL, 1),
(5524252, 796095, 30982, '<td valign="top">Nice catch of the sunlight in this one.  I also like how there''s a background (ie not all black) but it''s subtle.</td>', 'Nice catch of the sunlight in this one.  I also like how there''s a background (ie not all black) but it''s subtle.', '2009-06-11 16:25:41.000000', NULL, 1),
(5524253, 797350, 30982, '<td valign="top">Very clever!  Lovely shot of the animal as well - great tight pose, very good detail.</td>', 'Very clever!  Lovely shot of the animal as well - great tight pose, very good detail.', '2009-06-11 16:26:21.000000', NULL, 1),
(5524254, 797421, 30982, '<td valign="top">Looks like an Egyptian bird!  I like the almost painterly processing and you''ve used one of my favorite fonts.</td>', 'Looks like an Egyptian bird!  I like the almost painterly processing and you''ve used one of my favorite fonts.', '2009-06-11 16:26:59.000000', NULL, 1),
(5524255, 796693, 30982, '<td valign="top">Very nicely composed - the picture and the poster both.  Good use of color on the fonts to create a pleasing overall effect.  And a very pretty kitty!</td>', 'Very nicely composed - the picture and the poster both.  Good use of color on the fonts to create a pleasing overall effect.  And a very pretty kitty!', '2009-06-11 16:27:43.000000', NULL, 1),
