(5525078, 797276, 99263, '<td valign="top">Lovely colorful underwater image and makes a very nice promotional poster for this zoo.</td>', 'Lovely colorful underwater image and makes a very nice promotional poster for this zoo.', '2009-06-12 06:11:21.000000', NULL, 1),
(5525079, 797394, 99263, '<td valign="top">Nicely captured and makes a good promotional poster.</td>', 'Nicely captured and makes a good promotional poster.', '2009-06-12 06:11:31.000000', NULL, 1),
(5525081, 797480, 99263, '<td valign="top">Very nicely captured and makes a good promotional poster. Just needs the name of the zoo or farm somewhere.</td>', 'Very nicely captured and makes a good promotional poster. Just needs the name of the zoo or farm somewhere.', '2009-06-12 06:12:29.000000', NULL, 1),
(5525082, 796835, 99263, '<td valign="top">Very cool image and makes a wonderful promotional poster for this zoo.</td>', 'Very cool image and makes a wonderful promotional poster for this zoo.', '2009-06-12 06:13:01.000000', NULL, 1),
(5525083, 797096, 99263, '<td valign="top">Nicely captured and makes a good promotional poster.</td>', 'Nicely captured and makes a good promotional poster.', '2009-06-12 06:13:09.000000', NULL, 1),
(5525084, 797405, 99263, '<td valign="top">Nicely captured and makes a good promotional poster.</td>', 'Nicely captured and makes a good promotional poster.', '2009-06-12 06:13:16.000000', NULL, 1),
(5525085, 797404, 99263, '<td valign="top">Nicely captured and makes a good promotional poster.</td>', 'Nicely captured and makes a good promotional poster.', '2009-06-12 06:13:23.000000', NULL, 1),
(5525086, 797291, 99263, '<td valign="top">Nice enough image ( top of turtles head is over exposed)  but does not promote any zoo.</td>', 'Nice enough image ( top of turtles head is over exposed)  but does not promote any zoo.', '2009-06-12 06:14:40.000000', NULL, 1),
(5525087, 795947, 99263, '<td valign="top">Nicely captured and makes a good promotional poster.</td>', 'Nicely captured and makes a good promotional poster.', '2009-06-12 06:14:50.000000', NULL, 1),
(5525088, 795772, 99263, '<td valign="top">Visually striking image and makes an excellent promotional poster for this zoo.<br/>Lovely vibrant green.</td>', 'Visually striking image and makes an excellent promotional poster for this zoo.Lovely vibrant green.', '2009-06-12 06:15:41.000000', NULL, 1),
(5525089, 796993, 99263, '<td valign="top">Very icely captured and makes a very good promotional poster.</td>', 'Very icely captured and makes a very good promotional poster.', '2009-06-12 06:15:59.000000', NULL, 1),
(5525090, 797471, 99263, '<td valign="top">Cute and nicely captured. Does not promote any zoo though but I like the message here.</td>', 'Cute and nicely captured. Does not promote any zoo though but I like the message here.', '2009-06-12 06:17:18.000000', NULL, 1),
(5525454, 797448, 106349, '<td valign="top">Extremely beautiful picture, but not an ad!</td>', 'Extremely beautiful picture, but not an ad!', '2009-06-12 14:08:04.000000', NULL, 1),
(5525642, 797506, 86090, '<td valign="top">Absolutely beautiful, Great detail and nice contrast</td>', 'Absolutely beautiful, Great detail and nice contrast', '2009-06-12 17:47:46.000000', NULL, 1),
(5525643, 797283, 86090, '<td valign="top">This looks great!</td>', 'This looks great!', '2009-06-12 17:49:41.000000', NULL, 1),
(5525772, 796208, 62187, '<td valign="top">An excellent composition!</td>', 'An excellent composition!', '2009-06-12 20:13:31.000000', NULL, 1),
(5525779, 797275, 62187, '<td valign="top">I''ve never tried to photograph aquatic life so I''ll give you kudos for that!</td>', 'I''ve never tried to photograph aquatic life so I''ll give you kudos for that!', '2009-06-12 20:16:32.000000', NULL, 1),
(5525780, 797403, 62187, '<td valign="top">A very colorful specimen and perfectly framed.</td>', 'A very colorful specimen and perfectly framed.', '2009-06-12 20:17:09.000000', NULL, 1),
(5525782, 796993, 62187, '<td valign="top">What could I possibly add that would be slightly helpful. Nothing...you''ve got it all. I can help with a 10 that I doubt it will need.</td>', 'What could I possibly add that would be slightly helpful. Nothing...you''ve got it all. I can help with a 10 that I doubt it will need.', '2009-06-12 20:18:10.000000', NULL, 1),
(5525783, 797263, 62187, '<td valign="top">To me, it seems like a delightful and nicely executed out-of-the-box entry.</td>', 'To me, it seems like a delightful and nicely executed out-of-the-box entry.', '2009-06-12 20:19:20.000000', NULL, 1),
(5525785, 797448, 62187, '<td valign="top">I think a little more sharpness would make a better photo for what I''m getting on my monitor. Nicely framed and cropped.</td>', 'I think a little more sharpness would make a better photo for what I''m getting on my monitor. Nicely framed and cropped.', '2009-06-12 20:20:40.000000', NULL, 1),
(5525787, 797118, 62187, '<td valign="top">To me, it looks very bright: maybe a little over-exposed?</td>', 'To me, it looks very bright: maybe a little over-exposed?', '2009-06-12 20:22:24.000000', NULL, 1),
(5525789, 797444, 62187, '<td valign="top">For me, I''m seeing the main focus on the neck while I think it would look better with the face sharp too. Otherwise, it''s ''otterly'' perfect!</td>', 'For me, I''m seeing the main focus on the neck while I think it would look better with the face sharp too. Otherwise, it''s ''otterly'' perfect!', '2009-06-12 20:24:25.000000', NULL, 1),
(5525791, 797450, 62187, '<td valign="top">The focus is very nice but to me, the photo looks a little dark.</td>', 'The focus is very nice but to me, the photo looks a little dark.', '2009-06-12 20:25:17.000000', NULL, 1),
(5525793, 796693, 62187, '<td valign="top">Not much help photographically but I think it was really cool that you''ve added the Zoo''s address. Nice touch and the rest of the photo is perfect to me.</td>', 'Not much help photographically but I think it was really cool that you''ve added the Zoo''s address. Nice touch and the rest of the photo is perfect to me.', '2009-06-12 20:27:00.000000', NULL, 1),
(5525795, 797155, 62187, '<td valign="top">The photo is good - maybe it could be slightly sharper. I don''t like it when people comment solely on the ''frame'' but I really think a small thin white line between the photo and the border would have off-set the picture from the border much better. I dunno - I know nothing!</td>', 'The photo is good - maybe it could be slightly sharper. I don''t like it when people comment solely on the ''frame'' but I really think a small thin white line between the photo and the border would have off-set the picture from the border much better. I dunno - I know nothing!', '2009-06-12 20:30:05.000000', NULL, 1),
(5525796, 797408, 62187, '<td valign="top">That''s some super crisp focus and nicely framed.</td>', 'That''s some super crisp focus and nicely framed.', '2009-06-12 20:30:35.000000', NULL, 1),
(5525797, 797219, 62187, '<td valign="top">What a perfect shot for your ''slogan''!</td>', 'What a perfect shot for your ''slogan''!', '2009-06-12 20:31:21.000000', NULL, 1),
(5525802, 797394, 62187, '<td valign="top">If we could only teach the animals to wipe their faces when the pose for photos! For some reason, it looks like it was really windy when you took this. The focus on they eyes is very good.</td>', 'If we could only teach the animals to wipe their faces when the pose for photos! For some reason, it looks like it was really windy when you took this. The focus on they eyes is very good.', '2009-06-12 20:33:17.000000', NULL, 1),
(5525806, 797397, 62187, '<td valign="top">You''ve certainly done a great job with your photo in the edit.</td>', 'You''ve certainly done a great job with your photo in the edit.', '2009-06-12 20:34:25.000000', NULL, 1),
(5525808, 797486, 62187, '<td valign="top">How many times are you gonna get ''Awww, how cute is that! Well, at least one more I guess huh!?!?!?! The photo looks kinda noisy to me and out of focus here and there but it seems to be working for me. Nice work!</td>', 'How many times are you gonna get ''Awww, how cute is that! Well, at least one more I guess huh!?!?!?! The photo looks kinda noisy to me and out of focus here and there but it seems to be working for me. Nice work!', '2009-06-12 20:36:55.000000', NULL, 1),
(5525810, 795772, 62187, '<td valign="top">The photo part looks very serious. The lettering you''ve chosen looks playful. To me, they don''t go together but I think we should vote on the photo part which is awesome.</td>', 'The photo part looks very serious. The lettering you''ve chosen looks playful. To me, they don''t go together but I think we should vote on the photo part which is awesome.', '2009-06-12 20:38:32.000000', NULL, 1),
(5525812, 797421, 62187, '<td valign="top">I must say you''ve photographed an unusual character. Very colorful indeed!</td>', 'I must say you''ve photographed an unusual character. Very colorful indeed!', '2009-06-12 20:39:31.000000', NULL, 1),
(5525814, 797451, 62187, '<td valign="top">Well, I''m sure I''m not the first to say, or at least think, that some text would definitely improve this shot as a challenge entry. As a stand-alone photo, it''s awesome!</td>', 'Well, I''m sure I''m not the first to say, or at least think, that some text would definitely improve this shot as a challenge entry. As a stand-alone photo, it''s awesome!', '2009-06-12 20:40:46.000000', NULL, 1),
(5525817, 797482, 62187, '<td valign="top">Well, it''s absolutely weird enough for me to love! The title is trophy too...</td>', 'Well, it''s absolutely weird enough for me to love! The title is trophy too...', '2009-06-12 20:42:04.000000', NULL, 1),
(5525819, 797404, 62187, '<td valign="top">To me, the lettering being the same color as that animal is slightly distracting. I''m not sure what color would look better to me so maybe your choice was the best after all. The photo has very sharp focus and is nicely composed.</td>', 'To me, the lettering being the same color as that animal is slightly distracting. I''m not sure what color would look better to me so maybe your choice was the best after all. The photo has very sharp focus and is nicely composed.', '2009-06-12 20:44:01.000000', NULL, 1),
(5525820, 797480, 62187, '<td valign="top">It''s a great photo...but for the challenge, I think it''s a bit of a stretch as it looks more ''Farm'' like as opposed to ''Zoo-ish''</td>', 'It''s a great photo...but for the challenge, I think it''s a bit of a stretch as it looks more ''Farm'' like as opposed to ''Zoo-ish''', '2009-06-12 20:45:06.000000', NULL, 1),
(5525822, 797471, 62187, '<td valign="top">Excellent focus but I think a brave choice for a ''Zoo'' challenge.</td>', 'Excellent focus but I think a brave choice for a ''Zoo'' challenge.', '2009-06-12 20:45:53.000000', NULL, 1),
(5525823, 797283, 62187, '<td valign="top">An excellent photo and fun with text.</td>', 'An excellent photo and fun with text.', '2009-06-12 20:46:28.000000', NULL, 1),
(5525824, 796835, 62187, '<td valign="top">I don''t have a very good Zoo in my town either...sorry...I''m still grumpy. Whoa...I just saw his eye move!</td>', 'I don''t have a very good Zoo in my town either...sorry...I''m still grumpy. Whoa...I just saw his eye move!', '2009-06-12 20:47:48.000000', NULL, 1),
(5525825, 796809, 62187, '<td valign="top">A super nice find. To me, it looks a little bright and washed out. Maybe a tad bit more contrast? Could just be my monitor...</td>', 'A super nice find. To me, it looks a little bright and washed out. Maybe a tad bit more contrast? Could just be my monitor...', '2009-06-12 20:48:53.000000', NULL, 1),
(5525826, 797236, 62187, '<td valign="top">Ding, ding, ding...winner here! Not much ''helpful'' I could add to a perfect photo...</td>', 'Ding, ding, ding...winner here! Not much ''helpful'' I could add to a perfect photo...', '2009-06-12 20:49:48.000000', NULL, 1),
(5525827, 797509, 62187, '<td valign="top">Excellent photo!</td>', 'Excellent photo!', '2009-06-12 20:50:18.000000', NULL, 1),
