(5533151, 797291, 86090, '<td valign="top">That is a nice close up of the turtle. Now on the technical part the highlights on top of his head are blow out, if you shoot in raw you can recover some of it in pp. As you know lighting is very important in photography, but then again sometimes we take what we can get ;). It''s funny that you mention about the phrase you wanted to use, same thing happend to me, after I was done with pp, I couldn''t come up with anything =(</td>', 'That is a nice close up of the turtle. Now on the technical part the highlights on top of his head are blow out, if you shoot in raw you can recover some of it in pp. As you know lighting is very important in photography, but then again sometimes we take what we can get ;). It''s funny that you mention about the phrase you wanted to use, same thing happend to me, after I was done with pp, I couldn''t come up with anything =(', '2009-06-17 11:45:47.000000', NULL, 0),
(5533210, 797054, 107688, '<td valign="top">I am a newcmer, really like this shot and this web!</td>', 'I am a newcmer, really like this shot and this web!', '2009-06-17 12:29:06.000000', NULL, 0),
(5533557, 796713, 15305, '<td valign="top">Congratulations on a very well deserved blue and high score. This is such a wonderful photograph in every way!!</td>', 'Congratulations on a very well deserved blue and high score. This is such a wonderful photograph in every way!!', '2009-06-17 16:50:37.000000', NULL, 0),
(5533747, 796713, 77192, '<td valign="top">There''s no need to be modest...This is the best photo seen on DPC for quite some time, as is illustrated by the score. 37 10s is something really special in this day and age on DPC. Very well done to you. (It''d have been 38 if I got round to voting lol)<br/> <br/>The clarity of tones, the sharpness and details in this shot are truly exceptional.<br/> <br/>I can''t wait to see what you''ll get blue with next week ;-)</td>', 'There''s no need to be modest...This is the best photo seen on DPC for quite some time, as is illustrated by the score. 37 10s is something really special in this day and age on DPC. Very well done to you. (It''d have been 38 if I got round to voting lol) The clarity of tones, the sharpness and details in this shot are truly exceptional. I can''t wait to see what you''ll get blue with next week ;-)', '2009-06-17 18:22:54.000000', NULL, 0),
(5534872, 797408, 104091, '<td valign="top">Thank you all for your votes, comments and suggestions. It is much appreciated.</td>', 'Thank you all for your votes, comments and suggestions. It is much appreciated.', '2009-06-18 11:30:20.000000', NULL, 0),
(5536030, 797222, 31637, '<td valign="top">Hope its not a mouth breather...:(</td>', 'Hope its not a mouth breather...:(', '2009-06-19 02:59:30.000000', NULL, 0),
(5536360, 796993, 81530, '<td valign="top">Great shot Enzo!</td>', 'Great shot Enzo!', '2009-06-19 11:18:20.000000', NULL, 0),
(5536361, 796506, 81530, '<td valign="top">Congrats Lydia.</td>', 'Congrats Lydia.', '2009-06-19 11:18:30.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5536441, 796713, 37696, '<td valign="top">Incredible shot, but one thing I noticed is that you had no votes of 1, 2 or 3.  There is usually some troll that dings a great picture, but that didn''t happen here.  That''s an achievement in itself and testifies to how great a shot this is.</td>', 'Incredible shot, but one thing I noticed is that you had no votes of 1, 2 or 3.  There is usually some troll that dings a great picture, but that didn''t happen here.  That''s an achievement in itself and testifies to how great a shot this is.', '2009-06-19 12:15:02.000000', NULL, 0),
(5536971, 797435, 67145, '<td valign="top">oh well .. i did wonder about the border, but thought that coz it was obviously a border they''d allow it .. BUMMER .. !!!!<br/>it really is the most brilliant image .. reckon the virginia safari park would fall over themselves to use it for promotion .. :)</td>', 'oh well .. i did wonder about the border, but thought that coz it was obviously a border they''d allow it .. BUMMER .. !!!!it really is the most brilliant image .. reckon the virginia safari park would fall over themselves to use it for promotion .. :)', '2009-06-19 21:28:11.000000', NULL, 0),
(5538124, 796713, 73564, '<td valign="top">OMG! This is absolutley amazing! CONGRATS!</td>', 'OMG! This is absolutley amazing! CONGRATS!', '2009-06-21 01:03:03.000000', NULL, 0),
(5538520, 796506, 106806, '<td valign="top">Such an obviously great picture (apart from the zoof that gave it a 1 ... presumably an Omnian)<br/> <br/>How do you get the utterly white background?</td>', 'Such an obviously great picture (apart from the zoof that gave it a 1 ... presumably an Omnian) How do you get the utterly white background?', '2009-06-21 18:48:09.000000', NULL, 0),
(5539182, 797509, 30982, '<td valign="top">On my "too bright" at work monitor, there''s quite a bit of color noise on the kittie''s front paw and the dark area of the rock next to the kittie''s face.  You''d of course notice that if you tried to print it for the zoo.  Definitely a worthy shot!  And how cool that you''re promoting them in real life!</td>', 'On my "too bright" at work monitor, there''s quite a bit of color noise on the kittie''s front paw and the dark area of the rock next to the kittie''s face.  You''d of course notice that if you tried to print it for the zoo.  Definitely a worthy shot!  And how cool that you''re promoting them in real life!', '2009-06-22 05:49:33.000000', NULL, 0),
(5581982, 797411, 67145, '<td valign="top">brilliant shot wendy .. :)</td>', 'brilliant shot wendy .. :)', '2009-07-21 20:54:58.000000', NULL, 0),
(6302153, 797510, 91372, '<td valign="top">love this picture. going into my favorites.</td>', 'love this picture. going into my favorites.', '2011-02-03 14:49:17.000000', NULL, 0),
(6302163, 797510, 68586, '<td valign="top">Nice PoV and crop</td>', 'Nice PoV and crop', '2011-02-03 15:12:05.000000', NULL, 0),
